export class ErrorBoundary extends React.Component {
  state = { hasError: false, error: null };

  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }

  componentDidCatch(error, errorInfo) {
    console.error('Unhandled UI Crash:', error, errorInfo);
    // e.g. Sentry.captureException(error, { extra: errorInfo });
  }

  handleReset = () => {
    this.setState({ hasError: false, error: null });
  };

  render() {
    if (this.state.hasError) {
      return (
        <div className='p-6 bg-red-50 border border-red-200 rounded'>
          <h2 className='text-red-700 font-bold'>Something went wrong.</h2>
          <p className='text-sm text-gray-600 my-2'>{this.state.error?.message}</p>
          <button onClick={this.handleReset} className='px-4 py-2 bg-red-600 text-white rounded'>
            Try Again
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}
