function setupGracefulShutdown(server, db) {
  const shutdown = async (signal) => {
    console.log(`Received ${signal}. Starting graceful shutdown...`);

    // 1. Force kill process if cleanup hangs beyond 10 seconds
    const forceTimeout = setTimeout(() => {
      console.error('Graceful shutdown timed out. Forcing exit.');
      process.exit(1);
    }, 10000);
    forceTimeout.unref();

    // 2. Stop accepting new incoming HTTP connections
    server.close(async () => {
      console.log('HTTP server closed.');
      try {
        // 3. Drain database connections
        await db.close(); // e.g. mongoose.connection.close() or pool.end()
        console.log('Database connections closed cleanly.');
        process.exit(0);
      } catch (err) {
        console.error('Error during database teardown:', err);
        process.exit(1);
      }
    });
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT', () => shutdown('SIGINT'));
}
