import { pipeline } from 'stream/promises';
import fs from 'fs';
import zlib from 'zlib';
import { Transform } from 'stream';

export async function filterActiveRows(sourceGzPath, targetPath) {
  const rowFilter = new Transform({
    transform(chunk, encoding, callback) {
      const lines = chunk.toString().split('\n');
      const filtered = lines.filter(line => line.includes(',active,')).join('\n');
      this.push(filtered + '\n');
      callback();
    }
  });

  await pipeline(
    fs.createReadStream(sourceGzPath),
    zlib.createGunzip(),
    rowFilter,
    fs.createWriteStream(targetPath)
  );
  console.log('Stream pipeline completed with zero memory exhaustion.');
}
