Validating inputs at the middleware boundary ensures invalid or malicious payloads are rejected before reaching database queries or business controllers:
```javascript
import { z } from 'zod';

const registerSchema = z.object({
  email: z.string().email(),
  password: z.string().min(8).regex(/[A-Z]/, 'Must contain uppercase letter'),
  age: z.number().int().positive().optional()
});

export const validate = (schema) => (req, res, next) => {
  const result = schema.safeParse(req.body);
  if (!result.success) {
    return res.status(400).json({
      error: 'Validation failed',
      issues: result.error.errors.map(e => ({ field: e.path.join('.'), message: e.message }))
    });
  }
  req.validatedBody = result.data;
  next();
};
