export const responseEnvelope = (req, res, next) => {
  res.success = (data, statusCode = 200, meta = null) => {
    res.status(statusCode).json({
      success: true,
      data,
      ...(meta && { meta })
    });
  };

  res.fail = (message, statusCode = 400, details = null) => {
    res.status(statusCode).json({
      success: false,
      error: {
        message,
        statusCode,
        ...(details && { details })
      }
    });
  };

  next();
};
